<?php
require_once __DIR__.'/helpers.php';require_once __DIR__.'/../includes/deployment_secret_cipher.php';require_once __DIR__.'/../includes/deployment_connection_tester.php';
$cipher=new DeploymentSecretCipher(random_bytes(32));
test('credential encryption is randomized authenticated and context bound',function()use($cipher){$value='synthetic-test-credential';$first=$cipher->seal($value,'smtp:password');$second=$cipher->seal($value,'smtp:password');assertSameValue(false,$first===$second);assertSameValue(false,strpos($first,$value)!==false);assertSameValue($value,$cipher->open($first,'smtp:password'));try{$cipher->open($first,'sms:api_key');throw new LogicException('Swapped ciphertext accepted');}catch(RuntimeException$error){assertContains('verified',$error->getMessage());}});
test('wrong deployment key and modified authentication tag fail closed',function()use($cipher){$sealed=$cipher->seal('synthetic','context');try{(new DeploymentSecretCipher(random_bytes(32)))->open($sealed,'context');throw new LogicException('Wrong key accepted');}catch(RuntimeException$error){assertContains('verified',$error->getMessage());}$data=json_decode($sealed,true);$data['tag']=base64_encode(str_repeat('x',16));try{$cipher->open(json_encode($data),'context');throw new LogicException('Modified tag accepted');}catch(RuntimeException$error){assertContains('verified',$error->getMessage());}});
test('secret request fingerprints are keyed and stable',function()use($cipher){assertSameValue($cipher->fingerprint('same'),$cipher->fingerprint('same'));assertSameValue(false,hash('sha256','same')===$cipher->fingerprint('same'));assertSameValue(false,$cipher->fingerprint('same')===$cipher->fingerprint('different'));});
test('missing or disabled connections do not invoke network clients',function(){$calls=0;$tester=new DeploymentConnectionTester(function()use(&$calls){$calls++;return true;},function()use(&$calls){$calls++;return true;});assertSameValue(false,$tester->test('smtp',null)['network_tested']);assertSameValue(false,$tester->test('paystack',['enabled'=>false])['network_tested']);assertSameValue(0,$calls);});
test('read-only connection adapters receive server secrets but never return them',function(){$calls=[];$tester=new DeploymentConnectionTester(function($config,$secrets)use(&$calls){$calls[]='smtp';assertSameValue('synthetic-password',$secrets['password']);return true;},function($config,$secrets)use(&$calls){$calls[]='paystack';assertSameValue('sk_test_synthetic',$secrets['secret_key']);return true;});$smtp=$tester->test('smtp',['enabled'=>true,'config'=>[],'secrets'=>['password'=>'synthetic-password']]);$paystack=$tester->test('paystack',['enabled'=>true,'config'=>[],'secrets'=>['secret_key'=>'sk_test_synthetic']]);assertSameValue(['smtp','paystack'],$calls);assertSameValue(true,$smtp['connected']);assertSameValue(true,$paystack['network_tested']);assertSameValue(false,strpos(json_encode([$smtp,$paystack]),'synthetic')!==false);});
test('custom SMS remains explicitly unsupported without invoking arbitrary network requests',function(){$tester=new DeploymentConnectionTester(fn()=>throw new LogicException('Network forbidden'),fn()=>throw new LogicException('Network forbidden'));$result=$tester->test('sms',['enabled'=>true,'config'=>['endpoint_url'=>'https://example.invalid'],'secrets'=>[]]);assertSameValue(false,$result['network_tested']);assertSameValue('adapter_not_implemented',$result['reason']);});
finishTests();
